<script setup lang="ts">import {computed,ref} from 'vue';import {useRoute} from 'vue-router';import {Heart,Minus,Plus,ShoppingBag,Star,Truck,ShieldCheck,Clock} from 'lucide-vue-next';import {products,money} from '../data';import {useShopStore} from '../stores/shop';import ProductCard from '../components/ProductCard.vue';const route=useRoute();const store=useShopStore();const qty=ref(1);const p=computed(()=>products.find(x=>x.id===route.params.id));const related=computed(()=>products.filter(x=>x.category===p.value?.category&&x.id!==p.value?.id).slice(0,4));</script><template><section v-if="p" class="section"><div class="container product-detail"><div class="detail-image"><img :src="p.image" :alt="p.name"><span class="tag">{{p.tags[0]}}</span></div><div class="detail-copy"><div class="rating"><Star :size="16" fill="currentColor"/> {{p.rating}} <span>({{p.reviews}} verified reviews)</span></div><h1>{{p.name}}</h1><p class="arabic large">{{p.nameAr}}</p><strong class="detail-price">{{money(p.price)}}</strong><p class="description">{{p.description}}</p><div class="info-pills"><span v-if="p.servings">Serves: {{p.servings}}</span><span>Freshly baked</span></div><div v-if="p.allergens" class="allergens"><b>Contains:</b> {{p.allergens.join(', ')}}</div><div class="purchase"><div class="qty"><button @click="qty=Math.max(1,qty-1)"><Minus :size="17"/></button><b>{{qty}}</b><button @click="qty++"><Plus :size="17"/></button></div><button class="btn primary grow" @click="store.add(p,qty)"><ShoppingBag :size="18"/> Add to Cart · {{money(p.price*qty)}}</button><button class="icon-btn" :class="{active:store.wishlist.includes(p.id)}" @click="store.toggleWish(p.id)"><Heart :fill="store.wishlist.includes(p.id)?'currentColor':'none'"/></button></div><div class="detail-trust"><span><Truck/> Delivery across Kuwait</span><span><Clock/> Same-day before 2 PM</span><span><ShieldCheck/> Freshness guaranteed</span></div></div></div></section><section v-if="related.length" class="section alt"><div class="container"><div class="section-head"><div><span class="eyebrow">You May Also Like</span><h2>More to Love</h2></div></div><div class="product-grid"><ProductCard v-for="x in related" :key="x.id" :product="x"/></div></div></section></template>
